1	import React from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { defineMessages, useIntl } from 'react-intl';
4	
5	const messages = defineMessages({
6	  positionLabel: {
7	    id: 'slide_indicator.position.label',
8	    defaultMessage: 'Image {current} of {total}',
9	  },
10	});
11	
12	const ZIMM_SLIDE_INDICATOR_RECIPE = 'ZimmSlideIndicator';
13	
14	type ZimmSlideIndicatorProps = {
15	  /** Total number of images/slides the strip represents. */
16	  count: number;
17	  /** Index (0-based) of the currently active/visible slide. Out-of-range values are clamped. */
18	  activeIndex: number;
19	};
20	
21	/**
22	 * Molecule — read-only image-position indicator for touch devices (tablet + mobile) on the
23	 * PDP/card image strip. Figma node 40002536:7957 ("Slide indicator"): a segmented 1px hairline
24	 * strip, one segment per image, the active segment picked out by colour. NOT floating dots.
25	 *
26	 * Touch-only per the resolved arrows-vs-indicator split (SFCC-236 plan §4a): hover-capable
27	 * pointers get prev/next arrow buttons instead (a separate component) and never render this
28	 * molecule. Because no arrows exist wherever this DOES render, it is the *sole* position signal
29	 * available there — the root is exposed (`role="group"` + a computed `aria-label`), never
30	 * `aria-hidden`, while the individual segments are purely decorative (`aria-hidden`) so
31	 * assistive tech announces the position once via the group label, not once per segment.
32	 *
33	 * Renders nothing for `count <= 1` — a single image has no position to indicate among.
34	 */
35	export const ZimmSlideIndicator = ({ count, activeIndex }: ZimmSlideIndicatorProps) => {
36	  const intl = useIntl();
37	
38	  // Out-of-range clamps rather than throwing: activeIndex < 0 treats as the first slide,
39	  // activeIndex >= count treats as the last. Written explicitly rather than relying on
40	  // Array.map/index lookups to silently no-op on an out-of-range value.
41	  const clampedIndex = Math.min(Math.max(activeIndex, 0), count - 1);
42	
43	  // Two static resolutions (isActive: false / true), not one per rendered segment — calling
44	  // useMultiStyleConfig inside the render loop below would be a conditional/looped hook call.
45	  // Which of the two resolved objects applies to a given segment is picked per-element in the
46	  // map below instead.
47	  const styles = useMultiStyleConfig(ZIMM_SLIDE_INDICATOR_RECIPE, { isActive: false });
48	  const activeStyles = useMultiStyleConfig(ZIMM_SLIDE_INDICATOR_RECIPE, { isActive: true });
49	
50	  // A single image has nothing to indicate a position among.
51	  if (count <= 1) return null;
52	
53	  const label = intl.formatMessage(messages.positionLabel, {
54	    current: clampedIndex + 1,
55	    total: count,
56	  });
57	
58	  return (
59	    <chakra.div role="group" aria-label={label} __css={styles.root}>
60	      {Array.from({ length: count }, (_, i) => {
61	        const isActive = i === clampedIndex;
62	        return (
63	          <chakra.div
64	            key={i}
65	            aria-hidden
66	            data-active={isActive ? 'true' : undefined}
67	            __css={isActive ? activeStyles.dot : styles.dot}
68	          />
69	        );
70	      })}
71	    </chakra.div>
72	  );
73	};
74	
75	export default ZimmSlideIndicator;
76

1	import React from 'react';
2	import { describe, test, expect, vi } from 'vitest';
3	import { render, screen } from '@testing-library/react';
4	import { IntlProvider } from 'react-intl';
5	import { ZimmSlideIndicator } from './index';
6	
7	// The recipe's actual colour/geometry values aren't relevant to this component's own contract
8	// (segment count, which one is active, accessibility) — mock the same flat-parts shape the
9	// zimmColourSwatchGroup test uses so no real Chakra theme is needed.
10	vi.mock('@chakra-ui/react', async (importOriginal) => {
11	  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
12	  return {
13	    ...actual,
14	    useMultiStyleConfig: () => ({ root: {}, dot: {} }),
15	  };
16	});
17	
18	const wrap = (ui: React.ReactElement) =>
19	  render(
20	    <IntlProvider locale="en" defaultLocale="en">
21	      {ui}
22	    </IntlProvider>,
23	  );
24	
25	const segments = (container: HTMLElement) => Array.from(container.querySelectorAll('[aria-hidden="true"]'));
26	const activeSegments = (container: HTMLElement) => container.querySelectorAll('[data-active="true"]');
27	
28	describe('ZimmSlideIndicator — segment count', () => {
29	  test('renders exactly 5 segments for count=5', () => {
30	    const { container } = wrap(<ZimmSlideIndicator count={5} activeIndex={0} />);
31	    expect(segments(container)).toHaveLength(5);
32	  });
33	
34	  test('renders exactly 8 segments for count=8', () => {
35	    const { container } = wrap(<ZimmSlideIndicator count={8} activeIndex={0} />);
36	    expect(segments(container)).toHaveLength(8);
37	  });
38	});
39	
40	describe('ZimmSlideIndicator — exactly one active segment', () => {
41	  test('marks the first segment active when activeIndex=0', () => {
42	    const { container } = wrap(<ZimmSlideIndicator count={5} activeIndex={0} />);
43	    const active = activeSegments(container);
44	    expect(active).toHaveLength(1);
45	    expect(segments(container).indexOf(active[0])).toBe(0);
46	  });
47	
48	  test('marks the middle segment active', () => {
49	    const { container } = wrap(<ZimmSlideIndicator count={5} activeIndex={2} />);
50	    const active = activeSegments(container);
51	    expect(active).toHaveLength(1);
52	    expect(segments(container).indexOf(active[0])).toBe(2);
53	  });
54	
55	  test('marks the last segment active when activeIndex=count-1', () => {
56	    const { container } = wrap(<ZimmSlideIndicator count={5} activeIndex={4} />);
57	    const active = activeSegments(container);
58	    expect(active).toHaveLength(1);
59	    expect(segments(container).indexOf(active[0])).toBe(4);
60	  });
61	});
62	
63	describe('ZimmSlideIndicator — out-of-range activeIndex clamps rather than throwing', () => {
64	  test('activeIndex=-1 clamps to the first segment', () => {
65	    const { container } = wrap(<ZimmSlideIndicator count={5} activeIndex={-1} />);
66	    const active = activeSegments(container);
67	    expect(active).toHaveLength(1);
68	    expect(segments(container).indexOf(active[0])).toBe(0);
69	  });
70	
71	  test('activeIndex=count (one past the end) clamps to the last segment', () => {
72	    const { container } = wrap(<ZimmSlideIndicator count={5} activeIndex={5} />);
73	    const active = activeSegments(container);
74	    expect(active).toHaveLength(1);
75	    expect(segments(container).indexOf(active[0])).toBe(4);
76	  });
77	});
78	
79	describe('ZimmSlideIndicator — count <= 1 renders nothing', () => {
80	  test('count=0 renders nothing', () => {
81	    const { container } = wrap(<ZimmSlideIndicator count={0} activeIndex={0} />);
82	    expect(container.firstChild).toBeNull();
83	  });
84	
85	  test('count=1 renders nothing', () => {
86	    const { container } = wrap(<ZimmSlideIndicator count={1} activeIndex={0} />);
87	    expect(container.firstChild).toBeNull();
88	  });
89	});
90	
91	describe('ZimmSlideIndicator — accessibility (sole position signal on touch, see plan §4a)', () => {
92	  test('the root group is not aria-hidden', () => {
93	    wrap(<ZimmSlideIndicator count={5} activeIndex={1} />);
94	    const root = screen.getByRole('group');
95	    expect(root).not.toHaveAttribute('aria-hidden', 'true');
96	  });
97	
98	  test('the root exposes the current position as its accessible name', () => {
99	    wrap(<ZimmSlideIndicator count={5} activeIndex={1} />);
100	    expect(screen.getByRole('group', { name: 'Image 2 of 5' })).toBeInTheDocument();
101	  });
102	
103	  test('the accessible name reflects a clamped out-of-range activeIndex', () => {
104	    wrap(<ZimmSlideIndicator count={5} activeIndex={-1} />);
105	    expect(screen.getByRole('group', { name: 'Image 1 of 5' })).toBeInTheDocument();
106	  });
107	});
